  "search_result": null
}

{
  "analysis": "The reviewer describes payment-dependent matchmaking that allegedly gives paying players better teammates and non-paying players worse teammates, which is a monetized gameplay advantage and supports M_PayToProgress. The claim that the game selects teammates according to payment and rank describes hidden matchmaking manipulation, supporting P_IllusionOfControl. Team play, ranks, teammates, and losses establish player-versus-player competition, supporting S_Competition. T_Grinding, T_PlayingByAppointment, and other labels are not supported because no repetitive task, schedule, timer, or other qualifying mechanic is described.",
  "labels": [
    {
      "label": "M_PayToProgress",
      "span": "only if you invest some money in the game will the teammates will be good otherwise the game will select the worst ones for you",
      "rationale": "Payment is described as the route to a gameplay advantage through better teammates."
    },
    {
      "label": "P_IllusionOfControl",
      "span": "the game will select the worst ones for you and put them in your team",
      "rationale": "The span alleges that the game secretly manipulates matchmaking and team selection."
    },
    {
      "label": "S_Competition",
      "span": "everyone will just play solo and then blame you for the loss",
      "rationale": "The span describes team-based competitive play and losing against other players."
    }
  ],
  "invoked_web_search": false,
  "search_query": null,
  "search_result": null
}

{
  "analysis": "The review describes a casino-slot game and spending money in the app, so M_Gambling is a candidate; the span connects spending more money with trying to win. T_InfiniteTreadmill is rejected because \"impossible to ever win\" describes unsuccessful outcomes in a slot game, not an unattainable game completion state. No other label is supported: the review does not describe a specific reward-delivery mechanic, forced spending, repeated tasks, or a designed wait.",
  "labels": [
    {
      "label": "M_Gambling",
      "span": "why would I ever come back and spend more money when it is impossible to when",
      "rationale": "This describes spending real money in a casino-slot game while pursuing a chance-based win."
    }
  ],
  "invoked_web_search": false,
