  "labels": [
    {
      "label": "P_EasyToGetHardToLose",
      "span": "most are too invested to leave",
      "rationale": "Accumulated investment in the game is explicitly described as making players reluctant or unable to leave."
    }
  ],
  "invoked_web_search": false,
  "search_query": null,
  "search_result": null
